 public function options(Request $r){$flash=$r->query('kind')==='flash';$this->guard($r,$flash?'marketing.flash':($r->query('editing')?'products.manage':'products.create'));$fields=$this->fields($flash);$choices=['category_id'=>DB::table('categories')->orderBy('name')->get(['id','name']),'brand_id'=>DB::table('brands')->orderBy('name')->get(['id','name']),'flash_deal_id'=>FlashDeal::displayOrder()->get(['id','title'])->map(fn($x)=>['id'=>$x->id,'name'=>$x->title])];foreach($fields as &$f)if(isset($choices[$f['key']]))$f['options']=$choices[$f['key']];unset($f);$attributes=DB::table('attributes')->orderBy('id')->get(['id','name']);foreach($attributes as $a)$a->values=DB::table('attribute_values')->where('attribute_id',$a->id)->pluck('value');return $this->out(['fields'=>$fields,'attributes'=>$attributes,'colors'=>DB::table('colors')->orderBy('name')->get(['name','code']),'taxes'=>DB::table('taxes')->get(['id','name']),'shipping_managed'=>get_setting('shipping_type')!=='product_wise_shipping','cod_enabled'=>get_setting('cash_payment')=='1']);}
 public function media(Request $r){$this->guard($r,null);$r->validate(['page'=>'nullable|integer|min:1','type'=>'nullable|in:image,document']);$q=Upload::where('type',$r->query('type','image'));if($r->query('type')==='document')$q->where('extension','pdf');if($r->filled('search'))$q->where('file_original_name','like','%'.mb_substr($r->query('search'),0,100).'%');$p=$q->latest('id')->paginate(30);return $this->out(['data'=>$p->map(fn($u)=>$this->uploadDto($u))->all(),'page'=>$p->currentPage(),'last_page'=>$p->lastPage()]);}
 private function uploadDto($u){return ['id'=>(int)$u->id,'name'=>$u->file_original_name,'url'=>uploaded_asset($u->id),'type'=>$u->type];}
 public function upload(Request $r){$this->guard($r,null);$r->validate(['aiz_file'=>'required|file|max:10240|mimes:jpg,jpeg,png,webp,gif,avif,bmp,pdf']);$file=$r->file('aiz_file');$pdf=$file->getMimeType()==='application/pdf';if(!$pdf){$info=@getimagesize($file->getRealPath());abort_unless($info&&$info[0]*$info[1]<=40000000,422,'Select a valid image up to 40 megapixels.');}$this->session($r);$before=Upload::max('id')??0;(new AizUploadController())->upload($r);$u=Upload::where('id','>',$before)->where('user_id',$r->user()->id)->where('file_original_name',pathinfo($file->getClientOriginalName(),PATHINFO_FILENAME))->latest('id')->firstOrFail();return $this->out(['file'=>$this->uploadDto($u)]);}
 public function product(Request $r,$id){$this->guard($r,'products.manage');$p=Product::with('stocks')->findOrFail($id);$data=$p->toArray();$data['taxes']=$p->taxes()->get()->map(fn($t)=>['id'=>$t->tax_id,'value'=>$t->tax,'type'=>$t->tax_type])->all();$fd=$p->flash_deal_product;$data['flash_deal_id']=$fd?$fd->flash_deal_id:null;$data['tags_text']=$p->tags;$data['flat_shipping_cost']=$p->shipping_cost;$data['date_range']=$p->discount_start_date&&$p->discount_end_date?date('d-m-Y H:i:s',$p->discount_start_date).' to '.date('d-m-Y H:i:s',$p->discount_end_date):'';$media=[];foreach(['photos','thumbnail_img','meta_img','pdf']as $k){$media[$k]=Upload::whereIn('id',array_filter(explode(',',(string)$p->$k)))->get()->keyBy('id');$media[$k]=collect(array_filter(explode(',',(string)$p->$k)))->map(fn($id)=>isset($media[$k][$id])?$this->uploadDto($media[$k][$id]):null)->filter()->values();}if($p->pdf&&!ctype_digit((string)$p->pdf))$media['pdf']=[['legacy'=>$p->pdf,'name'=>'Existing PDF','type'=>'document']];$data['attributes']=[];foreach(json_decode($p->choice_options?:'[]',true)?:[]as $a)$data['attributes'][(string)$a['attribute_id']]=$a['values'];$data['colors']=json_decode($p->colors?:'[]',true)?:[];$data['variants']=$p->stocks->map(function($s){$u=$s->image?Upload::find($s->image):null;return ['name'=>$s->variant,'price'=>$s->price,'qty'=>$s->qty,'sku'=>(string)$s->sku,'image'=>$s->image,'file'=>$u?$this->uploadDto($u):null];})->all();return $this->out(['values'=>$data,'media'=>$media,'revision'=>$this->revision($p)]);}
 private function normalizeProduct($r,$existing=null){$legacyPdf=$existing&&!ctype_digit((string)$existing->pdf)&&$r->input("pdf")===$existing->pdf;$r->validate(['name'=>'required|string|max:255','category_id'=>'required|integer|exists:categories,id','brand_id'=>'nullable|integer|exists:brands,id','unit'=>'required|string|max:50','min_qty'=>'required|integer|min:1|max:99999','unit_price'=>'required|numeric|min:0|max:100000000','discount'=>'required|numeric|min:0','discount_type'=>'required|in:amount,percent','current_stock'=>'required|integer|min:0|max:1000000','stock_visibility_state'=>'required|in:quantity,text,hide','description'=>'nullable|string|max:200000','tags_text'=>'nullable|string|max:5000','attributes'=>'nullable|array|max:8','colors'=>'nullable|array|max:20','variants'=>'nullable|array|max:100','photos'=>'nullable|string','thumbnail_img'=>'nullable|string','meta_img'=>'nullable|integer|exists:uploads,id','pdf'=>$legacyPdf?'nullable|string|max:500':'nullable|integer|exists:uploads,id','button'=>'required|in:draft,unpublish,publish','taxes'=>'nullable|array|max:30','flash_deal_id'=>'nullable|integer|exists:flash_deals,id','flash_discount'=>'nullable|numeric|min:0','flash_discount_type'=>'nullable|in:amount,percent','low_stock_quantity'=>'nullable|integer|min:0','est_shipping_days'=>'nullable|integer|min:1','flat_shipping_cost'=>'nullable|numeric|min:0','shipping_type'=>'nullable|in:free,flat_rate']);if($r->discount_type==='percent')abort_if($r->discount>100,422,'Percent discount cannot exceed 100.');
 $tags=[];foreach(array_filter(array_map('trim',explode(',',$r->input('tags_text',''))))as $tag)$tags[]=['value'=>$tag];$r->merge(['tags'=>[json_encode($tags)],'lang'=>CatalogWriteInput::language()]);$attrs=$r->input('attributes',[]);$choice=[];$options=[];$colors=$r->input('colors',[]);if($colors){$names=[];foreach($colors as $code){$color=DB::table('colors')->where('code',$code)->first();abort_unless($color,422,'Choose valid colors.');$names[]=$color->name;}$options[]=$names;$r->merge(['colors_active'=>1]);}foreach($attrs as $id=>$values){if(!$values)continue;abort_unless(ctype_digit((string)$id)&&DB::table('attributes')->where('id',$id)->exists()&&is_array($values)&&count($values)<=30,422,'Choose valid attributes.');$allowed=DB::table('attribute_values')->where('attribute_id',$id)->pluck('value')->all();abort_if(array_diff($values,$allowed),422,'Choose valid attribute values.');$choice[]=(string)$id;$r->merge(['choice_options_'.$id=>array_values($values)]);$options[]=array_values($values);}$r->merge(['choice_no'=>$choice]);
 $combinations=$options?\Combinations::makeCombinations($options):[];abort_if(count($combinations)>100,422,'Use at most 100 variants.');$posted=collect($r->input('variants',[]))->keyBy('name');foreach($combinations as $combo){$name=implode('-',array_map(fn($v)=>str_replace(' ','',$v),$combo));$v=$posted->get($name);abort_unless($v&&isset($v['price'],$v['qty'])&&is_numeric($v['price'])&&$v['price']>=0&&filter_var($v['qty'],FILTER_VALIDATE_INT)!==false&&$v['qty']>=0&&$v['qty']<=1000000,422,'Enter price and stock for every variant.');$imageCheck=Request::create('/','POST',['thumbnail_img'=>isset($v['image'])?(string)$v['image']:null]);ProductPhotos::prepare($imageCheck);$key=str_replace('.','_',$name);$r->merge(['price_'.$key=>$v['price'],'qty_'.$key=>$v['qty'],'sku_'.$key=>mb_substr($v['sku']??'',0,100),'img_'.$key=>$v['image']??null]);}
 $taxIds=[];$taxValues=[];$taxTypes=[];foreach($r->input('taxes',[])as $tax){abort_unless(isset($tax['id'],$tax['value'],$tax['type'])&&DB::table('taxes')->where('id',$tax['id'])->exists()&&is_numeric($tax['value'])&&$tax['value']>=0&&in_array($tax['type'],['amount','percent']),422,'Enter valid taxes.');$taxIds[]=$tax['id'];$taxValues[]=$tax['value'];$taxTypes[]=$tax['type'];}$r->merge(['tax_id'=>$taxIds,'tax'=>$taxValues,'tax_type'=>$taxTypes]);ProductPhotos::prepare($r);if($r->filled('meta_img'))ProductPhotos::prepare(Request::create('/','POST',['thumbnail_img'=>(string)$r->meta_img]));if($r->filled('pdf')&&!$legacyPdf)abort_unless(Upload::where('id',$r->pdf)->where('extension','pdf')->exists(),422,'Choose a PDF specification.');CatalogWriteInput::prepare($r);}
 private function once($r,$kind,$call){$r->validate(['request_key'=>'required|uuid']);$key='native-catalog-save:'.hash('sha256',$r->user()->id.':'.$kind.':'.$r->request_key);$hash=hash('sha256',json_encode($r->all()));return Cache::lock($key.':lock',120)->block(5,function()use($key,$hash,$call){$prior=Cache::get($key);if($prior){abort_unless(hash_equals($prior['hash'],$hash),409,'This save was already used. Reopen the form before making more changes.');return $this->out($prior['data']);}$response=$call();if(DB::transactionLevel()===0)Cache::put($key,['hash'=>$hash,'data'=>$response->getData(true)],600);return $response;});}
 public function saveProduct(Request $r,$id=null){$this->guard($r,$id?'products.manage':'products.create');return $this->once($r,'product:'.($id??'new'),function()use($r,$id){$this->normalizeProduct($r,$id?Product::findOrFail($id):null);$this->session($r);$result=DB::transaction(function()use($r,$id){if($id){$p=Product::whereKey($id)->lockForUpdate()->firstOrFail();abort_unless(hash_equals($this->revision($p),(string)$r->input('revision')),409,'Product changed. Reopen it before saving.');$r->merge(['slug'=>$p->slug]);(new ProductController())->update($r,$id);$p->refresh();$p->published=$r->input('button')==='publish'?1:0;$p->save();}else{$slug=preg_replace('/[^A-Za-z0-9\-]/','',str_replace(' ','-',strtolower($r->name)));abort_if(!$slug||Product::where('slug',$slug)->exists(),422,'Another product uses this name. Choose a unique name.');(new ProductController())->store($r);$p=Product::where('slug',$slug)->firstOrFail();}DB::table('business_settings')->where('type','mobile_catalog_revision')->update(['value'=>DB::raw('CAST(value AS UNSIGNED)+1')]);$p->pdf=$r->input('pdf');$p->save();return ['id'=>$p->id,'published'=>(bool)$p->published,'message'=>'Product saved.'];});return $this->out($result);});}
 public function deals(Request $r){$this->guard($r,'marketing.flash');return $this->out(['data'=>FlashDeal::displayOrder()->get()->map(fn($f)=>['id'=>$f->id,'title'=>$f->title,'status'=>(bool)$f->status,'featured'=>(bool)$f->featured,'revision'=>$this->revision($f),'start'=>date('d M Y H:i',$f->start_date),'end'=>date('d M Y H:i',$f->end_date)])->all()]);}
 public function deal(Request $r,$id){$this->guard($r,'marketing.flash');$f=FlashDeal::findOrFail($id);$values=$f->toArray();$values['date_range']=date('d-m-Y H:i:s',$f->start_date).' to '.date('d-m-Y H:i:s',$f->end_date);$values['products']=$f->flash_deal_products()->orderBy('id')->get()->map(function($x){$p=Product::find($x->product_id);return $p?['id'=>$p->id,'name'=>$p->name,'discount'=>$p->discount,'discount_type'=>$p->discount_type]:null;})->filter()->values();$banner=$f->banner?Upload::find($f->banner):null;return $this->out(['values'=>$values,'media'=>['banner'=>$banner?[$this->uploadDto($banner)]:[]],'revision'=>$this->revision($f)]);}
 public function dealState(Request $r,$id){$this->guard($r,'marketing.flash');$r->validate(['revision'=>'required|string|size:64','action'=>'required|in:status,featured,position','value'=>'required|integer|min:0']);$this->session($r);DB::transaction(function()use($r,$id){$f=FlashDeal::whereKey($id)->lockForUpdate()->firstOrFail();abort_unless(hash_equals($this->revision($f),$r->revision),409,'Flash Deal changed. Refresh the list.');$c=new FlashDealController();$r->merge(['id'=>(int)$id]);if($r->action==='position'){$r->merge(['position'=>(int)$r->value]);$c->reorder($r);}else{abort_unless(in_array((int)$r->value,[0,1]),422);if($r->action==='status'){$r->merge(['status'=>(int)$r->value]);$c->update_status($r);}else{$r->merge(['featured'=>(int)$r->value]);$c->update_featured($r);}}DB::table('business_settings')->where('type','mobile_catalog_revision')->update(['value'=>DB::raw('CAST(value AS UNSIGNED)+1')]);});return $this->out(['message'=>'Flash Deal updated.']);}
 public function saveDeal(Request $r,$id=null){$this->guard($r,'marketing.flash');return $this->once($r,'deal:'.($id??'new'),function()use($r,$id){$r->validate(['title'=>'required|string|max:255','background_color'=>'required|regex:/^#[a-fA-F0-9]{6}$/D','text_color'=>'required|in:white,dark','date_range'=>'required|string|max:100','banner'=>'nullable|integer|exists:uploads,id','products'=>'required|array|min:1|max:1000','products.*.id'=>'required|integer|distinct|exists:products,id','products.*.discount'=>'required|numeric|min:0','products.*.discount_type'=>'required|in:amount,percent']);$selected=$r->input('products');$ids=[];foreach($selected as $p){abort_if($p['discount_type']==='percent'&&$p['discount']>100,422,'Percent discount cannot exceed 100.');$ids[]=$p['id'];$r->merge(['discount_'.$p['id']=>$p['discount'],'discount_type_'.$p['id']=>$p['discount_type']]);}$r->merge(['products'=>$ids,'ordered_products'=>$ids,'lang'=>CatalogWriteInput::language()]);if($r->filled('banner')){ $b=Request::create('/','POST',['thumbnail_img'=>(string)$r->banner]);ProductPhotos::prepare($b);}CatalogWriteInput::prepare($r,true);$this->session($r);$result=DB::transaction(function()use($r,$id){if($id){$f=FlashDeal::whereKey($id)->lockForUpdate()->firstOrFail();abort_unless(hash_equals($this->revision($f),(string)$r->input('revision')),409,'Flash Deal changed. Reopen it before saving.');(new FlashDealController())->update($r,$id);}else{$before=FlashDeal::max('id')??0;(new FlashDealController())->store($r);$f=FlashDeal::where('id','>',$before)->where('title',$r->title)->latest('id')->firstOrFail();}DB::table('business_settings')->where('type','mobile_catalog_revision')->update(['value'=>DB::raw('CAST(value AS UNSIGNED)+1')]);return ['id'=>$f->id,'message'=>'Flash Deal saved.'];});return $this->out($result);});}
